<?php
declare(strict_types=1);
require dirname(__DIR__,2).'/app/bootstrap.php';
require dirname(__DIR__,2).'/app/advance/AdminLayout.php';
require dirname(__DIR__,2).'/app/DestinationAdminService.php';
if (isset($_SESSION['admin']) && time()-(int)($_SESSION['last_seen']??0)>1800) unset($_SESSION['admin']);
if (empty($_SESSION['admin'])) { http_response_code(403); exit('Inicia sesión desde el panel de administración.'); }
$_SESSION['last_seen']=time();
$service=new DestinationAdminService(db());$error='';$saved=false;$id=max(0,(int)($_GET['id']??$_POST['id']??0));
try {
    if ($_SERVER['REQUEST_METHOD']==='POST') {
        csrf();$action=(string)($_POST['action']??'save');
        if ($action==='save') {
            $publicRoot=getenv('EL_ADMIN_MEDIA_ROOT')?:($_SERVER['DOCUMENT_ROOT']??'');
            if (!$publicRoot) throw new RuntimeException('No se encontró la carpeta pública para guardar imágenes.');
            $id=$service->save($_POST,$_FILES['hero_upload']??[],$_FILES['place_uploads']??[],$publicRoot);header('Location: destinos.php?id='.$id.'&saved=1',true,303);exit;
        }
        if ($action==='archive'&&$id>0) {$service->archive($id);header('Location: destinos.php?saved=archived',true,303);exit;}
        if ($action==='delete'&&$id>0) {$service->delete($id);header('Location: destinos.php?saved=deleted',true,303);exit;}
        throw new RuntimeException('Acción no válida.');
    }
} catch (Throwable $e) { $error=$e instanceof PDOException?'No se guardó el destino. Revisa que el identificador no esté repetido y que la base tenga la migración dinámica.':$e->getMessage();http_response_code(400); }
$record=$id>0?$service->find($id):null;
if($id>0&&!$record&&$error===''){$error='No existe un destino con ese ID.';http_response_code(404);}
$rows=$service->all();$media=$service->mediaOptions();$locales=['es'=>'Español','en'=>'English','pt-BR'=>'Português (Brasil)'];
function field_value(array $record,string $section,string $locale,string $key,string $fallback=''): string { return (string)($record[$section][$locale][$key]??$fallback); }
function text_lines(array $record,string $section,string $locale): string { return implode("\n",$record[$section][$locale]??[]); }
function source_lines(array $record,string $locale): string { return implode("\n",array_map(static fn($s)=>$s['section_key'].'|'.$s['source_label'].'|'.$s['source_url'],$record['sources'][$locale]??[])); }
