    $es=$place['translations']['es']??[];$isEmpty=empty($place['id'])&&empty($es['name']);
    ?><details class="destination-place" data-place-row data-empty-placeholder="<?=$isEmpty?'1':'0'?>" <?=$i===0?'open':''?>><summary><?=esc($es['name']??('Atractivo '.($i+1)))?></summary><div class="destination-form-grid">
    <?php if(isset($place['id'])):?><input type="hidden" name="places[<?=$i?>][id]" value="<?=esc($place['id'])?>"><?php endif ?>
