    <label class="wide">Nombre<input data-place-locale="es" data-place-key="name" name="places[<?=$i?>][translations][es][name]" maxlength="180" value="<?=esc($es['name']??'')?>" placeholder="Ej. Parque principal"></label>
    <label class="wide">Descripción breve<textarea data-place-locale="es" data-place-key="description" name="places[<?=$i?>][translations][es][description]" rows="2" maxlength="5000" placeholder="¿Qué encontrará allí la persona visitante?"><?=esc($es['description']??'')?></textarea></label>
    <label class="wide">Imagen para esta tarjeta<select name="places[<?=$i?>][media_asset_id]"><option value="0">Sin imagen existente</option><?php foreach($media as $asset):?><option value="<?=esc($asset['id'])?>" <?=((int)($place['media_asset_id']??0)===(int)$asset['id'])?'selected':''?>><?=esc($asset['asset_path'])?></option><?php endforeach ?></select><small>También puedes subir una imagen nueva debajo.</small></label>
