<script>
(()=>{
 const form=document.querySelector('.destination-editor'),container=document.querySelector('.destination-editor fieldset:nth-of-type(2)'),template=document.getElementById('destination-place-template'),add=document.getElementById('add-destination-place'),file=document.getElementById('destination-package-file'),status=document.getElementById('destination-import-status');
 if(!form||!container||!template||!add||!file)return;
 const rows=()=>[...container.querySelectorAll('[data-place-row]')];
 function addRow(){const index=rows().length;const holder=document.createElement('div');holder.innerHTML=template.innerHTML.replace(/places\[0\]/g,`places[${index}]`);const row=holder.firstElementChild;row.querySelector('summary').textContent=`Atractivo ${index+1}`;row.querySelectorAll('input:not([type=hidden]),textarea').forEach(el=>{if(el.type!=='file')el.value='';});row.querySelectorAll('input[type=hidden]').forEach(el=>el.value='');container.insertBefore(row,add);return row;}
 add.addEventListener('click',()=>{if(rows().length>=40){status.textContent='Un destino admite hasta 40 atractivos.';return;}addRow().open=true;});
 const publication=form.elements.namedItem('publication_status'),saveButton=form.querySelector('button[type="submit"]');
 if(publication&&saveButton){const updateSaveLabel=()=>saveButton.textContent=publication.value==='published'?'Guardar y publicar':(publication.value==='archived'?'Guardar y retirar del sitio':'Guardar como borrador');publication.addEventListener('change',updateSaveLabel);updateSaveLabel();form.addEventListener('submit',event=>{if(publication.value==='published'&&!confirm('Esto publicará el destino y sus atractivos aprobados para los visitantes. ¿Continuar?'))event.preventDefault();});}
 const set=(name,value)=>{const el=form.elements.namedItem(name);if(el&&(typeof value==='string'||typeof value==='number'))el.value=String(value);};
 const list=(v)=>Array.isArray(v)?v.join('\n'):(typeof v==='string'?v:'');
 file.addEventListener('change',async()=>{const selected=file.files&&file.files[0];if(!selected)return;status.textContent='Leyendo paquete…';try{if(selected.size>2*1024*1024)throw new Error('El paquete JSON debe pesar 2 MB o menos.');const pack=JSON.parse(await selected.text());if(pack.schema_version!==1||!pack.destination||!Array.isArray(pack.places))throw new Error('El archivo no corresponde al formato de paquete de destino v1.');if(pack.places.length>40)throw new Error('Un paquete puede incluir hasta 40 atractivos.');if(!confirm('Se rellenarán los campos del formulario con este paquete. Los datos escritos se reemplazarán; los atractivos existentes que falten se archivarán. Todavía no se guardará nada. ¿Continuar?')){file.value='';status.textContent='Importación cancelada.';return;}
 const d=pack.destination,translations=d.translations||{};set('slug',d.slug||'');set('department',d.department||'Antioquia');set('subregion',d.subregion||'');set('latitude',d.latitude??'');set('longitude',d.longitude??'');
 for(const locale of ['es','en','pt-BR']){const t=translations[locale]||{};for(const key of ['display_name','eyebrow','headline','intro','meta_description'])set(`translations[${locale}][${key}]`,t[key]||'');set(`history[${locale}]`,list((d.history||{})[locale]));set(`reasons[${locale}]`,list((d.reasons||{})[locale]));const sources=((d.sources||{})[locale]||[]).map(s=>typeof s==='string'?s:`${s.section||'destination'}|${s.label||''}|${s.url||''}`).join('\n');set(`sources[${locale}]`,sources);}
 const hero=pack.hero_image||{};set('image_origin',hero.image_origin||'ai_generated');for(const key of ['image_creator','image_source_url','image_license','image_license_url'])set(key,hero[key]||'');for(const locale of ['es','en','pt-BR']){set(`image_alt[${locale}]`,(hero.alt||{})[locale]||'');set(`image_caption[${locale}]`,(hero.caption||{})[locale]||'');}set('internal_research_json',JSON.stringify(pack.local_research||{schema_version:1},null,2));
 let cards=rows();while(cards.length<pack.places.length&&cards.length<40){addRow();cards=rows();}form.querySelectorAll('input[type="file"]').forEach(el=>{el.value='';});cards.forEach((card,index)=>{const p=pack.places[index];const state=card.querySelector('[name$="[publication_status]"]');if(!p){const existingId=card.querySelector('[name$="[id]"]');if(existingId){card.dataset.emptyPlaceholder='0';if(state)state.value='archived';}else{card.dataset.emptyPlaceholder='1';if(state)state.value='draft';card.querySelectorAll('input:not([type=hidden]),textarea').forEach(el=>{if(el.type!=='file')el.value='';});const slug=card.querySelector('[name$="[slug]"]');if(slug)slug.value='';}return;}card.dataset.emptyPlaceholder='0';if(state)state.value=p.publication_status||'draft';for(const locale of ['es','en','pt-BR'])for(const key of ['name','description']){const el=card.querySelector(`[data-place-locale="${locale}"][data-place-key="${key}"]`);if(el)el.value=((p.translations||{})[locale]||{})[key]||'';}const image=p.image||{};for(const key of ['image_origin','image_creator','image_source_url','image_license','image_license_url']){const el=card.querySelector(`[name$="[${key}]"]`);if(el)el.value=image[key]||(key==='image_origin'?'ai_generated':'');}for(const locale of ['es','en','pt-BR'])for(const key of ['alt','caption']){const el=card.querySelector(`[name$="[${key}][${locale}]"]`);if(el)el.value=((image[key]||{})[locale])||'';}const slug=card.querySelector('[name$="[slug]"]');if(slug)slug.value=p.slug||'';const summary=card.querySelector('summary');if(summary)summary.textContent=((p.translations||{}).es||{}).name||`Atractivo ${index+1}`;});
